const topic = String($json.topic ?? '');
const payload = String($json.message ?? '');
const receivedAt = new Date().toISOString();

const topicMap = {
  'smartfish/telemetry/suhu_air': { group: 'telemetry', key: 'suhu_air_c', unit: 'degC' },
  'smartfish/telemetry/suhu_wadah': { group: 'telemetry', key: 'suhu_wadah_c', unit: 'degC' },
  'smartfish/telemetry/kelembapan': { group: 'telemetry', key: 'kelembapan_percent', unit: 'percent' },
  'smartfish/telemetry/jarak_pakan': { group: 'telemetry', key: 'jarak_pakan_cm', unit: 'cm' },
  'smartfish/telemetry/jarak_air': { group: 'telemetry', key: 'jarak_air_cm', unit: 'cm' },
  'smartfish/status/servo': { group: 'status', key: 'servo' },
  'smartfish/status/device': { group: 'status', key: 'device' },
};

const spec = topicMap[topic];
if (!spec) {
  throw new Error(`Unexpected Smart Fish topic: ${topic}`);
}

const state = $getWorkflowStaticData('global');
if (!state.smartFishFeeder) {
  state.smartFishFeeder = { telemetry: {}, status: {} };
}
const deviceState = state.smartFishFeeder;

if (spec.group === 'telemetry') {
  const numericValue = Number(payload.trim());
  const validNumber = payload.trim() !== '' && Number.isFinite(numericValue);
  deviceState.telemetry[spec.key] = validNumber
    ? { value: numericValue, unit: spec.unit, updated_at: receivedAt }
    : { value: null, unit: spec.unit, updated_at: receivedAt, raw_value: payload, parse_error: true };
} else {
  deviceState.status[spec.key] = { value: payload.trim(), updated_at: receivedAt };
}
deviceState.updated_at = receivedAt;

return {
  json: {
    device_id: 'smartfish',
    timestamp: receivedAt,
    source: { topic, payload },
    telemetry: deviceState.telemetry,
    status: deviceState.status,
    updated_at: deviceState.updated_at,
  },
};
